package com.dunerealms.clans;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import org.junit.jupiter.api.*;
import java.sql.*;
import java.math.BigDecimal;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;
import java.lang.reflect.Method;
import org.bukkit.entity.Player;
import com.example.dunegui.NativeMenus;
class ClanWalletTest {
 String url;ClanStore store;ClanStore.Context ctx;
 @BeforeEach void setup()throws Exception{url="jdbc:h2:mem:"+UUID.randomUUID()+";MODE=MySQL;DATABASE_TO_LOWER=TRUE;DB_CLOSE_DELAY=-1;LOCK_TIMEOUT=5000";ctx=new ClanStore.Context("00000000-0000-0000-0009-000000000001","clan-1","member","Aerdrecht","AED",1,"blueprint-1",2,"Desert Kit","#c8ae62","[]",100);store=new ClanStore((c,u)->ctx);try(Connection c=open()){ClanStore.initialize(c);ClanStore.initialize(c);try(Statement s=c.createStatement()){s.execute("CREATE TABLE dune_economy_balances(uuid VARCHAR(36) PRIMARY KEY,balance DECIMAL(20,2) NOT NULL)");}}}
 Connection open()throws SQLException{return DriverManager.getConnection(url);}
 void seed(String amount)throws Exception{try(Connection c=open();PreparedStatement s=c.prepareStatement("INSERT INTO dune_economy_balances VALUES(?,?)")){s.setString(1,ctx.uuid());s.setBigDecimal(2,new BigDecimal(amount));s.executeUpdate();}}
 long count(Connection c,String table)throws Exception{try(Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT COUNT(*) FROM "+table)){r.next();return r.getLong(1);}}
 void balance(Connection c,String expected)throws Exception{assertEquals(0,new BigDecimal(expected).compareTo(store.wallet(c,UUID.fromString(ctx.uuid()))));}
 @Test void debitAndReceiptUseOnlyWalletDunemarks()throws Exception{seed("250.25");try(Connection c=open()){c.setAutoCommit(false);UUID id=UUID.randomUUID();store.operation(c,id,ctx,"kit-purchase");store.payDunemarks(c,ctx);store.orderDunemarks(c,id,ctx);c.commit();balance(c,"150.25");assertEquals(0,count(c,"dune_clan_bank_balances"));assertEquals(0,count(c,"dune_clan_bank_ledger"));try(Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT cost_spice,cost_dunemarks,payment_currency,funding,grades_json FROM dune_clan_kit_orders")){assertTrue(r.next());assertEquals(0,r.getLong(1));assertEquals(0,new BigDecimal("100").compareTo(r.getBigDecimal(2)));assertEquals("dunemarks",r.getString(3));assertEquals("wallet",r.getString(4));assertEquals("{}",r.getString(5));}}}
 @Test void overdraftAndUnknownUuidNeverCreateMoneyOrBankRows()throws Exception{seed("99.99");try(Connection c=open()){c.setAutoCommit(false);assertThrows(SQLException.class,()->store.payDunemarks(c,ctx));c.rollback();balance(c,"99.99");var unknown=new ClanStore.Context(UUID.randomUUID().toString(),ctx.clan(),ctx.role(),ctx.name(),ctx.tag(),1,ctx.blueprint(),2,ctx.kitName(),ctx.color(),ctx.lore(),100);assertThrows(SQLException.class,()->store.payDunemarks(c,unknown));c.rollback();assertEquals(1,count(c,"dune_economy_balances"));assertEquals(0,count(c,"dune_clan_bank_ledger"));}}
 @Test void rollbackRestoresWalletOperationAndKitReceipt()throws Exception{seed("250");try(Connection c=open()){c.setAutoCommit(false);UUID id=UUID.randomUUID();store.operation(c,id,ctx,"kit-purchase");store.payDunemarks(c,ctx);store.orderDunemarks(c,id,ctx);balance(c,"150");assertEquals(1,count(c,"dune_clan_kit_orders"));c.rollback();balance(c,"250");assertEquals(0,count(c,"dune_clan_operations"));assertEquals(0,count(c,"dune_clan_kit_orders"));assertEquals(0,count(c,"dune_clan_bank_balances"));assertEquals(0,count(c,"dune_clan_bank_ledger"));}}
 @Test void replayFailsBeforeSecondDebit()throws Exception{seed("250");UUID id=UUID.randomUUID();try(Connection c=open()){c.setAutoCommit(false);store.operation(c,id,ctx,"kit-purchase");store.payDunemarks(c,ctx);store.orderDunemarks(c,id,ctx);c.commit();assertThrows(SQLException.class,()->{store.operation(c,id,ctx,"kit-purchase");store.payDunemarks(c,ctx);store.orderDunemarks(c,id,ctx);});c.rollback();balance(c,"150");assertEquals(1,count(c,"dune_clan_kit_orders"));}}
 @Test void simultaneousWalletPurchasesCannotOverdraw()throws Exception{seed("150");ExecutorService pool=Executors.newFixedThreadPool(2);CountDownLatch start=new CountDownLatch(1);AtomicInteger successes=new AtomicInteger();Callable<Void> buy=()->{try(Connection c=open()){c.setAutoCommit(false);start.await();try{UUID id=UUID.randomUUID();store.operation(c,id,ctx,"kit-purchase");store.payDunemarks(c,ctx);store.orderDunemarks(c,id,ctx);c.commit();successes.incrementAndGet();}catch(SQLException denied){c.rollback();}}return null;};try{var a=pool.submit(buy);var b=pool.submit(buy);start.countDown();a.get(10,TimeUnit.SECONDS);b.get(10,TimeUnit.SECONDS);}finally{pool.shutdownNow();}assertEquals(1,successes.get());try(Connection c=open()){balance(c,"50");assertEquals(1,count(c,"dune_clan_operations"));assertEquals(1,count(c,"dune_clan_kit_orders"));assertEquals(0,count(c,"dune_clan_bank_balances"));assertEquals(0,count(c,"dune_clan_bank_ledger"));}}
 @Test void walletWritesRequireFence()throws Exception{seed("250");try(Connection c=open()){assertThrows(SQLException.class,()->store.payDunemarks(c,ctx));assertThrows(SQLException.class,()->store.orderDunemarks(c,UUID.randomUUID(),ctx));balance(c,"250");}}
 @Test void migrationKeepsHistoricalSpiceReceiptAndIsIdempotent()throws Exception{try(Connection c=open()){c.setAutoCommit(false);UUID id=UUID.randomUUID();store.order(c,id,ctx,"clan-bank",Map.of(ClanStore.Grade.common,100L));c.commit();try(Statement ddl=c.createStatement()){ddl.execute("ALTER TABLE dune_clan_kit_orders DROP COLUMN cost_dunemarks");ddl.execute("ALTER TABLE dune_clan_kit_orders DROP COLUMN payment_currency");}ClanStore.initialize(c);ClanStore.initialize(c);try(Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT cost_spice,cost_dunemarks,payment_currency,grades_json FROM dune_clan_kit_orders")){r.next();assertEquals(100,r.getLong(1));assertEquals(0,r.getBigDecimal(2).signum());assertEquals("spice",r.getString(3));assertEquals("{\"common\":100}",r.getString(4));}}}
 @Test void shopOffersWalletOnlyAndCallsPurchasePreview()throws Exception{DuneClans plugin=mock(DuneClans.class,CALLS_REAL_METHODS);Player p=mock(Player.class);when(p.isOnline()).thenReturn(true);when(p.hasPermission("dune.clans.view")).thenReturn(true);var balances=new EnumMap<ClanStore.Grade,Long>(ClanStore.Grade.class);for(var g:ClanStore.Grade.values())balances.put(g,500L);var view=new DuneClans.View(ctx,new BigDecimal("500"),new BigDecimal("250"),List.of());Method show=DuneClans.class.getDeclaredMethod("show",Player.class,String.class,DuneClans.View.class);show.setAccessible(true);try(var menus=mockStatic(NativeMenus.class)){menus.when(()->NativeMenus.show(eq(plugin),eq(p),anyString(),anyString(),anyList())).thenAnswer(call->{String body=call.getArgument(3);List<NativeMenus.Choice> choices=call.getArgument(4);assertTrue(body.contains("100 Dunemarks"));assertTrue(choices.stream().anyMatch(x->x.label().equals("Buy kit — Dunemarks wallet")));assertFalse(choices.stream().anyMatch(x->x.label().contains("inventory spice")||x.label().contains("clan bank")));return null;});show.invoke(plugin,p,"shop",view);menus.verify(()->NativeMenus.show(eq(plugin),eq(p),anyString(),anyString(),anyList()),times(1));}}
}
